package nvt.vn.ute_forum.controller;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.UserPrincipal;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.service.NotificationService;
import nvt.vn.ute_forum.service.UsersService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;

@Controller
public class RoleNotificationController {

    private final UsersService usersService;
    private final NotificationService notificationService;

    public RoleNotificationController(UsersService usersService, NotificationService notificationService) {
        this.usersService = usersService;
        this.notificationService = notificationService;
    }

    @GetMapping("/staff/notifications")
    public String showStaffNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                         @RequestParam(value = "filter", defaultValue = "all") String filter,
                                         Authentication authentication,
                                         Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_DEPARTMENT".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        populateNotificationModel(model, user, tab, filter);
        model.addAttribute("staff", user);
        return "staff/staff-notification";
    }

    @PostMapping("/staff/notifications/delete")
    public String deleteStaffNotification(@RequestParam("notificationId") String notificationId,
                                          @RequestParam(value = "tab", defaultValue = "all") String tab,
                                          @RequestParam(value = "filter", defaultValue = "all") String filter,
                                          Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_DEPARTMENT".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/staff/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    @GetMapping("/admin/notifications")
    public String showAdminNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                         @RequestParam(value = "filter", defaultValue = "all") String filter,
                                         Authentication authentication,
                                         Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_ADMIN".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        populateNotificationModel(model, user, tab, filter);
        model.addAttribute("admin", user);
        return "admin/admin-notification";
    }

    @PostMapping("/admin/notifications/delete")
    public String deleteAdminNotification(@RequestParam("notificationId") String notificationId,
                                          @RequestParam(value = "tab", defaultValue = "all") String tab,
                                          @RequestParam(value = "filter", defaultValue = "all") String filter,
                                          Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_ADMIN".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/admin/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    private void populateNotificationModel(Model model, Users user, String tab, String filter) {
        List<NotificationItem> allItems = notificationService.getByUserId(user.getId())
                .stream()
                .map(this::toItem)
                .toList();

        List<NotificationItem> byTab = allItems.stream()
                .filter(item -> matchesTab(item, tab))
                .toList();

        List<NotificationItem> displayedItems = byTab.stream()
                .filter(item -> matchesReadFilter(item, filter))
                .toList();

        model.addAttribute("activeTab", normalizeTab(tab));
        model.addAttribute("activeFilter", normalizeFilter(filter));
        model.addAttribute("notifications", displayedItems);
        model.addAttribute("countAll", allItems.size());
        model.addAttribute("countFeedback", allItems.stream().filter(item -> "feedback".equals(item.tabKey())).count());
        model.addAttribute("countForum", allItems.stream().filter(item -> "forum".equals(item.tabKey())).count());
    }

    private NotificationItem toItem(Notification notification) {
        String tabKey = tabByType(notification.getNotificationType());
        String icon = iconByType(notification.getNotificationType());
        String iconClass = iconClassByType(notification.getNotificationType());
        String title = notification.getTitle() == null || notification.getTitle().isBlank()
                ? "Thong bao"
                : notification.getTitle();
        String content = notification.getContent() == null ? "" : notification.getContent();
        String timeLabel = humanTime(notification.getCreateAt());
        boolean isRead = Boolean.TRUE.equals(notification.getRead());
        return new NotificationItem(notification.getId(), title, content, timeLabel, icon, iconClass, tabKey, isRead);
    }

    private String tabByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("FEEDBACK") || normalized.contains("REPORT")) {
            return "feedback";
        }
        if (normalized.contains("FORUM") || normalized.contains("COMMENT") || normalized.contains("VOTE")) {
            return "forum";
        }
        return "all";
    }

    private String iconByType(String type) {
        String tab = tabByType(type);
        if ("feedback".equals(tab)) {
            return "!";
        }
        if ("forum".equals(tab)) {
            return "";
        }
        return "✉";
    }

    private String iconClassByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("RESOLVED") || normalized.contains("APPROVED")) {
            return "icon-success";
        }
        if (normalized.contains("PROCESSING") || normalized.contains("FORWARDED")) {
            return "icon-processing";
        }
        if (normalized.contains("COMMENT") || normalized.contains("VOTE") || normalized.contains("FORUM")) {
            return "icon-forum";
        }
        return "icon-default";
    }

    private String normalizeType(String type) {
        return type == null ? "" : type.trim().toUpperCase(Locale.ROOT);
    }

    private String humanTime(LocalDateTime createdAt) {
        if (createdAt == null) {
            return "vua xong";
        }

        long days = ChronoUnit.DAYS.between(createdAt, LocalDateTime.now());
        if (days <= 0) {
            return "hom nay";
        }
        if (days == 1) {
            return "1 ngay";
        }
        if (days < 30) {
            return days + " ngay";
        }
        if (days < 365) {
            return (days / 30) + " thang";
        }
        return (days / 365) + " nam";
    }

    private boolean matchesTab(NotificationItem item, String tab) {
        String normalized = normalizeTab(tab);
        if ("all".equals(normalized)) {
            return true;
        }
        return normalized.equals(item.tabKey());
    }

    private boolean matchesReadFilter(NotificationItem item, String filter) {
        String normalized = normalizeFilter(filter);
        if ("all".equals(normalized)) {
            return true;
        }
        if ("read".equals(normalized)) {
            return item.read();
        }
        return !item.read();
    }

    private String normalizeTab(String tab) {
        if (tab == null) {
            return "all";
        }
        String normalized = tab.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "feedback", "forum" -> normalized;
            default -> "all";
        };
    }

    private String normalizeFilter(String filter) {
        if (filter == null) {
            return "all";
        }
        String normalized = filter.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "read", "unread" -> normalized;
            default -> "all";
        };
    }

    private Users resolveAuthenticatedUser(Authentication authentication) {
        if (authentication == null || !authentication.isAuthenticated()) {
            return null;
        }

        Object principal = authentication.getPrincipal();
        String email = null;

        if (principal instanceof UserPrincipal userPrincipal) {
            email = userPrincipal.getUsername();
        } else if (principal instanceof UserDetails userDetails) {
            email = userDetails.getUsername();
        } else if (principal instanceof String principalName) {
            email = principalName;
        }

        if (email == null || email.isBlank() || "anonymousUser".equalsIgnoreCase(email)) {
            return null;
        }

        return usersService.getByEmail(email.trim());
    }

    private record NotificationItem(String id,
                                    String title,
                                    String content,
                                    String timeLabel,
                                    String icon,
                                    String iconClass,
                                    String tabKey,
                                    boolean read) {
    }
}

package nvt.vn.ute_forum.controller;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.UserPrincipal;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.service.NotificationService;
import nvt.vn.ute_forum.service.UsersService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;

@Controller
public class RoleNotificationController {

    private final UsersService usersService;
    private final NotificationService notificationService;

    public RoleNotificationController(UsersService usersService, NotificationService notificationService) {
        this.usersService = usersService;
        this.notificationService = notificationService;
    }

    @GetMapping("/staff/notifications")
    public String showStaffNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                         @RequestParam(value = "filter", defaultValue = "all") String filter,
                                         Authentication authentication,
                                         Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_DEPARTMENT".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        populateNotificationModel(model, user, tab, filter);
        model.addAttribute("staff", user);
        return "staff/staff-notification";
    }

    @PostMapping("/staff/notifications/delete")
    public String deleteStaffNotification(@RequestParam("notificationId") String notificationId,
                                          @RequestParam(value = "tab", defaultValue = "all") String tab,
                                          @RequestParam(value = "filter", defaultValue = "all") String filter,
                                          Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_DEPARTMENT".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/staff/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    @GetMapping("/admin/notifications")
    public String showAdminNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                         @RequestParam(value = "filter", defaultValue = "all") String filter,
                                         Authentication authentication,
                                         Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_ADMIN".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        populateNotificationModel(model, user, tab, filter);
        model.addAttribute("admin", user);
        return "admin/admin-notification";
    }

    @PostMapping("/admin/notifications/delete")
    public String deleteAdminNotification(@RequestParam("notificationId") String notificationId,
                                          @RequestParam(value = "tab", defaultValue = "all") String tab,
                                          @RequestParam(value = "filter", defaultValue = "all") String filter,
                                          Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }
        if (!"ROLE_ADMIN".equalsIgnoreCase(user.getRole())) {
            return "redirect:/api/forum/view";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/admin/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    private void populateNotificationModel(Model model, Users user, String tab, String filter) {
        List<NotificationItem> allItems = notificationService.getByUserId(user.getId())
                .stream()
                .map(notification -> toItem(notification, user))
                .toList();

        List<NotificationItem> byTab = allItems.stream()
                .filter(item -> matchesTab(item, tab))
                .toList();

        List<NotificationItem> displayedItems = byTab.stream()
                .filter(item -> matchesReadFilter(item, filter))
                .toList();

        model.addAttribute("activeTab", normalizeTab(tab));
        model.addAttribute("activeFilter", normalizeFilter(filter));
        model.addAttribute("notifications", displayedItems);
        model.addAttribute("countAll", allItems.size());
        model.addAttribute("countFeedback", allItems.stream().filter(item -> "feedback".equals(item.tabKey())).count());
        model.addAttribute("countForum", allItems.stream().filter(item -> "forum".equals(item.tabKey())).count());
    }

    private NotificationItem toItem(Notification notification, Users user) {
        String tabKey = tabByType(notification.getNotificationType());
        String icon = iconByType(notification.getNotificationType());
        String iconClass = iconClassByType(notification.getNotificationType());
        String title = notification.getTitle() == null || notification.getTitle().isBlank()
                ? "Thong bao"
                : notification.getTitle();
        String content = notificationService.cleanContent(notification.getContent());
        String timeLabel = humanTime(notification.getCreateAt());
        boolean isRead = Boolean.TRUE.equals(notification.getRead());
        String targetUrl = buildTargetUrl(notification, user);
        return new NotificationItem(notification.getId(), title, content, timeLabel, icon, iconClass, tabKey, isRead, targetUrl);
    }

    private String buildTargetUrl(Notification notification, Users user) {
        if (notification == null || user == null) {
            return null;
        }

        return notificationService.resolveRequestId(notification)
                .map(requestId -> forumDetailBasePath(user) + "/" + requestId)
                .orElse(null);
    }

    private String forumDetailBasePath(Users user) {
        if (user == null || user.getRole() == null) {
            return "/api/forum";
        }

        if ("ROLE_ADMIN".equalsIgnoreCase(user.getRole())) {
            return "/admin/forum";
        }
        if ("ROLE_DEPARTMENT".equalsIgnoreCase(user.getRole())) {
            return "/api/forum/staff";
        }
        return "/api/forum";
    }

    private String tabByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("FEEDBACK") || normalized.contains("REPORT")) {
            return "feedback";
        }
        if (normalized.contains("FORUM") || normalized.contains("COMMENT") || normalized.contains("VOTE")) {
            return "forum";
        }
        return "all";
    }

    private String iconByType(String type) {
        String tab = tabByType(type);
        if ("feedback".equals(tab)) {
            return "!";
        }
        if ("forum".equals(tab)) {
            return "";
        }
        return "✉";
    }

    private String iconClassByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("RESOLVED") || normalized.contains("APPROVED")) {
            return "icon-success";
        }
        if (normalized.contains("PROCESSING") || normalized.contains("FORWARDED")) {
            return "icon-processing";
        }
        if (normalized.contains("COMMENT") || normalized.contains("VOTE") || normalized.contains("FORUM")) {
            return "icon-forum";
        }
        return "icon-default";
    }

    private String normalizeType(String type) {
        return type == null ? "" : type.trim().toUpperCase(Locale.ROOT);
    }

    private String humanTime(LocalDateTime createdAt) {
        if (createdAt == null) {
            return "vua xong";
        }

        long days = ChronoUnit.DAYS.between(createdAt, LocalDateTime.now());
        if (days <= 0) {
            return "hom nay";
        }
        if (days == 1) {
            return "1 ngay";
        }
        if (days < 30) {
            return days + " ngay";
        }
        if (days < 365) {
            return (days / 30) + " thang";
        }
        return (days / 365) + " nam";
    }

    private boolean matchesTab(NotificationItem item, String tab) {
        String normalized = normalizeTab(tab);
        if ("all".equals(normalized)) {
            return true;
        }
        return normalized.equals(item.tabKey());
    }

    private boolean matchesReadFilter(NotificationItem item, String filter) {
        String normalized = normalizeFilter(filter);
        if ("all".equals(normalized)) {
            return true;
        }
        if ("read".equals(normalized)) {
            return item.read();
        }
        return !item.read();
    }

    private String normalizeTab(String tab) {
        if (tab == null) {
            return "all";
        }
        String normalized = tab.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "feedback", "forum" -> normalized;
            default -> "all";
        };
    }

    private String normalizeFilter(String filter) {
        if (filter == null) {
            return "all";
        }
        String normalized = filter.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "read", "unread" -> normalized;
            default -> "all";
        };
    }

    private Users resolveAuthenticatedUser(Authentication authentication) {
        if (authentication == null || !authentication.isAuthenticated()) {
            return null;
        }

        Object principal = authentication.getPrincipal();
        String email = null;

        if (principal instanceof UserPrincipal userPrincipal) {
            email = userPrincipal.getUsername();
        } else if (principal instanceof UserDetails userDetails) {
            email = userDetails.getUsername();
        } else if (principal instanceof String principalName) {
            email = principalName;
        }

        if (email == null || email.isBlank() || "anonymousUser".equalsIgnoreCase(email)) {
            return null;
        }

        return usersService.getByEmail(email.trim());
    }

    private record NotificationItem(String id,
                                    String title,
                                    String content,
                                    String timeLabel,
                                    String icon,
                                    String iconClass,
                                    String tabKey,
                                    boolean read,
                                    String targetUrl) {
    }
}

package nvt.vn.ute_forum.controller;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.UserPrincipal;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.service.NotificationService;
import nvt.vn.ute_forum.service.UsersService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;

@Controller
public class StudentNotificationController {

    private final UsersService usersService;
    private final NotificationService notificationService;

    public StudentNotificationController(UsersService usersService, NotificationService notificationService) {
        this.usersService = usersService;
        this.notificationService = notificationService;
    }

    @GetMapping("/api/notifications")
    public String showNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                    @RequestParam(value = "filter", defaultValue = "all") String filter,
                                    Authentication authentication,
                                    Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }

        List<NotificationItem> allItems = notificationService.getByUserId(user.getId())
                .stream()
                .map(this::toItem)
                .toList();

        List<NotificationItem> byTab = allItems.stream()
                .filter(item -> matchesTab(item, tab))
                .toList();

        List<NotificationItem> displayedItems = byTab.stream()
                .filter(item -> matchesReadFilter(item, filter))
                .toList();

        model.addAttribute("user", user);
        model.addAttribute("roleLabel", "Sinh vien");
        model.addAttribute("activeTab", normalizeTab(tab));
        model.addAttribute("activeFilter", normalizeFilter(filter));
        model.addAttribute("notifications", displayedItems);
        model.addAttribute("countAll", allItems.size());
        model.addAttribute("countFeedback", allItems.stream().filter(item -> "feedback".equals(item.tabKey())).count());
        model.addAttribute("countForum", allItems.stream().filter(item -> "forum".equals(item.tabKey())).count());
        return "student/notification";
    }

    @PostMapping("/api/notifications/delete")
    public String deleteNotification(@RequestParam("notificationId") String notificationId,
                                     @RequestParam(value = "tab", defaultValue = "all") String tab,
                                     @RequestParam(value = "filter", defaultValue = "all") String filter,
                                     Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/api/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    private NotificationItem toItem(Notification notification) {
        String tabKey = tabByType(notification.getNotificationType());
        String icon = iconByType(notification.getNotificationType());
        String iconClass = iconClassByType(notification.getNotificationType());
        String title = notification.getTitle() == null || notification.getTitle().isBlank()
                ? "Thông báo"
                : notification.getTitle();
        String content = notification.getContent() == null ? "" : notification.getContent();
        String timeLabel = humanTime(notification.getCreateAt());
        boolean isRead = Boolean.TRUE.equals(notification.getRead());
        return new NotificationItem(notification.getId(), title, content, timeLabel, icon, iconClass, tabKey, isRead);
    }

    private String tabByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("FEEDBACK") || normalized.contains("REPORT")) {
            return "feedback";
        }
        if (normalized.contains("FORUM") || normalized.contains("COMMENT") || normalized.contains("VOTE")) {
            return "forum";
        }
        return "all";
    }

    private String iconByType(String type) {
        String tab = tabByType(type);
        if ("feedback".equals(tab)) {
            return "✓";
        }
        if ("forum".equals(tab)) {
            return "";
        }
        return "✉";
    }

    private String iconClassByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("RESOLVED") || normalized.contains("APPROVED")) {
            return "icon-success";
        }
        if (normalized.contains("PROCESSING") || normalized.contains("FORWARDED")) {
            return "icon-processing";
        }
        if (normalized.contains("COMMENT") || normalized.contains("VOTE") || normalized.contains("FORUM")) {
            return "icon-forum";
        }
        return "icon-default";
    }

    private String normalizeType(String type) {
        return type == null ? "" : type.trim().toUpperCase(Locale.ROOT);
    }

    private String humanTime(LocalDateTime createdAt) {
        if (createdAt == null) {
            return "vừa xong";
        }

        long days = ChronoUnit.DAYS.between(createdAt, LocalDateTime.now());
        if (days <= 0) {
            return "hôm nay";
        }
        if (days == 1) {
            return "1 ngày";
        }
        if (days < 30) {
            return days + " ngày";
        }
        if (days < 365) {
            return (days / 30) + " tháng";
        }
        return (days / 365) + " năm";
    }

    private boolean matchesTab(NotificationItem item, String tab) {
        String normalized = normalizeTab(tab);
        if ("all".equals(normalized)) {
            return true;
        }
        return normalized.equals(item.tabKey());
    }

    private boolean matchesReadFilter(NotificationItem item, String filter) {
        String normalized = normalizeFilter(filter);
        if ("all".equals(normalized)) {
            return true;
        }
        if ("read".equals(normalized)) {
            return item.read();
        }
        return !item.read();
    }

    private String normalizeTab(String tab) {
        if (tab == null) {
            return "all";
        }
        String normalized = tab.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "feedback", "forum" -> normalized;
            default -> "all";
        };
    }

    private String normalizeFilter(String filter) {
        if (filter == null) {
            return "all";
        }
        String normalized = filter.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "read", "unread" -> normalized;
            default -> "all";
        };
    }


    private Users resolveAuthenticatedUser(Authentication authentication) {
        if (authentication == null || !authentication.isAuthenticated()) {
            return null;
        }

        Object principal = authentication.getPrincipal();
        String email = null;

        if (principal instanceof UserPrincipal userPrincipal) {
            email = userPrincipal.getUsername();
        } else if (principal instanceof UserDetails userDetails) {
            email = userDetails.getUsername();
        } else if (principal instanceof String principalName) {
            email = principalName;
        }

        if (email == null || email.isBlank() || "anonymousUser".equalsIgnoreCase(email)) {
            return null;
        }

        return usersService.getByEmail(email.trim());
    }

    private record NotificationItem(String id,
                                    String title,
                                    String content,
                                    String timeLabel,
                                    String icon,
                                    String iconClass,
                                    String tabKey,
                                    boolean read) {
    }
}

package nvt.vn.ute_forum.controller;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.UserPrincipal;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.service.NotificationService;
import nvt.vn.ute_forum.service.UsersService;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;

@Controller
public class StudentNotificationController {

    private final UsersService usersService;
    private final NotificationService notificationService;

    public StudentNotificationController(UsersService usersService, NotificationService notificationService) {
        this.usersService = usersService;
        this.notificationService = notificationService;
    }

    @GetMapping("/api/notifications")
    public String showNotifications(@RequestParam(value = "tab", defaultValue = "all") String tab,
                                    @RequestParam(value = "filter", defaultValue = "all") String filter,
                                    Authentication authentication,
                                    Model model) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }

        List<NotificationItem> allItems = notificationService.getByUserId(user.getId())
                .stream()
                .map(notification -> toItem(notification, user))
                .toList();

        List<NotificationItem> byTab = allItems.stream()
                .filter(item -> matchesTab(item, tab))
                .toList();

        List<NotificationItem> displayedItems = byTab.stream()
                .filter(item -> matchesReadFilter(item, filter))
                .toList();

        model.addAttribute("user", user);
        model.addAttribute("roleLabel", "Sinh vien");
        model.addAttribute("activeTab", normalizeTab(tab));
        model.addAttribute("activeFilter", normalizeFilter(filter));
        model.addAttribute("notifications", displayedItems);
        model.addAttribute("countAll", allItems.size());
        model.addAttribute("countFeedback", allItems.stream().filter(item -> "feedback".equals(item.tabKey())).count());
        model.addAttribute("countForum", allItems.stream().filter(item -> "forum".equals(item.tabKey())).count());
        return "student/notification";
    }

    @PostMapping("/api/notifications/delete")
    public String deleteNotification(@RequestParam("notificationId") String notificationId,
                                     @RequestParam(value = "tab", defaultValue = "all") String tab,
                                     @RequestParam(value = "filter", defaultValue = "all") String filter,
                                     Authentication authentication) {
        Users user = resolveAuthenticatedUser(authentication);
        if (user == null) {
            return "redirect:/login";
        }

        notificationService.deleteForUser(notificationId, user.getId());
        return "redirect:/api/notifications?tab=" + normalizeTab(tab) + "&filter=" + normalizeFilter(filter);
    }

    private NotificationItem toItem(Notification notification, Users user) {
        String tabKey = tabByType(notification.getNotificationType());
        String icon = iconByType(notification.getNotificationType());
        String iconClass = iconClassByType(notification.getNotificationType());
        String title = notification.getTitle() == null || notification.getTitle().isBlank()
                ? "Thông báo"
                : notification.getTitle();
        String content = notificationService.cleanContent(notification.getContent());
        String timeLabel = humanTime(notification.getCreateAt());
        boolean isRead = Boolean.TRUE.equals(notification.getRead());
        String targetUrl = notificationService.resolveRequestId(notification)
                .map(requestId -> "/api/forum/" + requestId)
                .orElse(null);
        return new NotificationItem(notification.getId(), title, content, timeLabel, icon, iconClass, tabKey, isRead, targetUrl);
    }

    private String tabByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("FEEDBACK") || normalized.contains("REPORT")) {
            return "feedback";
        }
        if (normalized.contains("FORUM") || normalized.contains("COMMENT") || normalized.contains("VOTE")) {
            return "forum";
        }
        return "all";
    }

    private String iconByType(String type) {
        String tab = tabByType(type);
        if ("feedback".equals(tab)) {
            return "✓";
        }
        if ("forum".equals(tab)) {
            return "";
        }
        return "✉";
    }

    private String iconClassByType(String type) {
        String normalized = normalizeType(type);
        if (normalized.contains("RESOLVED") || normalized.contains("APPROVED")) {
            return "icon-success";
        }
        if (normalized.contains("PROCESSING") || normalized.contains("FORWARDED")) {
            return "icon-processing";
        }
        if (normalized.contains("COMMENT") || normalized.contains("VOTE") || normalized.contains("FORUM")) {
            return "icon-forum";
        }
        return "icon-default";
    }

    private String normalizeType(String type) {
        return type == null ? "" : type.trim().toUpperCase(Locale.ROOT);
    }

    private String humanTime(LocalDateTime createdAt) {
        if (createdAt == null) {
            return "vừa xong";
        }

        long days = ChronoUnit.DAYS.between(createdAt, LocalDateTime.now());
        if (days <= 0) {
            return "hôm nay";
        }
        if (days == 1) {
            return "1 ngày";
        }
        if (days < 30) {
            return days + " ngày";
        }
        if (days < 365) {
            return (days / 30) + " tháng";
        }
        return (days / 365) + " năm";
    }

    private boolean matchesTab(NotificationItem item, String tab) {
        String normalized = normalizeTab(tab);
        if ("all".equals(normalized)) {
            return true;
        }
        return normalized.equals(item.tabKey());
    }

    private boolean matchesReadFilter(NotificationItem item, String filter) {
        String normalized = normalizeFilter(filter);
        if ("all".equals(normalized)) {
            return true;
        }
        if ("read".equals(normalized)) {
            return item.read();
        }
        return !item.read();
    }

    private String normalizeTab(String tab) {
        if (tab == null) {
            return "all";
        }
        String normalized = tab.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "feedback", "forum" -> normalized;
            default -> "all";
        };
    }

    private String normalizeFilter(String filter) {
        if (filter == null) {
            return "all";
        }
        String normalized = filter.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "read", "unread" -> normalized;
            default -> "all";
        };
    }


    private Users resolveAuthenticatedUser(Authentication authentication) {
        if (authentication == null || !authentication.isAuthenticated()) {
            return null;
        }

        Object principal = authentication.getPrincipal();
        String email = null;

        if (principal instanceof UserPrincipal userPrincipal) {
            email = userPrincipal.getUsername();
        } else if (principal instanceof UserDetails userDetails) {
            email = userDetails.getUsername();
        } else if (principal instanceof String principalName) {
            email = principalName;
        }

        if (email == null || email.isBlank() || "anonymousUser".equalsIgnoreCase(email)) {
            return null;
        }

        return usersService.getByEmail(email.trim());
    }

    private record NotificationItem(String id,
                                    String title,
                                    String content,
                                    String timeLabel,
                                    String icon,
                                    String iconClass,
                                    String tabKey,
                                    boolean read,
                                    String targetUrl) {
    }
}

