            commentRepo.save(c);
        });
    }

    @Transactional
    public Comment save(Comment comment) {
        return commentRepo.save(comment);
    }

}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.repository.NotificationRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
public class NotificationService {

    @Autowired
    private NotificationRepo notificationRepo;

    public List<Notification> getByUserId(String userId) {
        return notificationRepo.findByUsers_IdOrderByCreateAtDesc(userId);
    }

    public long countUnreadByUserId(String userId) {
        return notificationRepo.countByUsers_IdAndIsReadFalse(userId);
    }

    @Transactional
    public boolean deleteForUser(String notificationId, String userId) {
        if (notificationId == null || notificationId.isBlank() || userId == null || userId.isBlank()) {
            return false;
        }

        if (!notificationRepo.existsByIdAndUsers_Id(notificationId, userId)) {
            return false;
        }

        int affectedRows = notificationRepo.unlinkNotificationFromUser(notificationId, userId);
        if (affectedRows <= 0) {
            return false;
        }

        if (notificationRepo.countReceivers(notificationId) == 0) {
            notificationRepo.deleteById(notificationId);
        }

        return true;
    }
}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.VoteComment;
import nvt.vn.ute_forum.model.VoteCommentId;
import nvt.vn.ute_forum.model.VoteId;
import nvt.vn.ute_forum.repository.CommentRepo;
import nvt.vn.ute_forum.repository.NotificationRepo;
import nvt.vn.ute_forum.repository.VoteCommentRepo;
import nvt.vn.ute_forum.repository.VoteRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Service
public class NotificationService {

    @Autowired
    private NotificationRepo notificationRepo;

    @Autowired
    private CommentRepo commentRepo;

    @Autowired
    private VoteCommentRepo voteCommentRepo;

    @Autowired
    private VoteRepo voteRepo;

    public List<Notification> getByUserId(String userId) {
        return notificationRepo.findByUsers_IdOrderByCreateAtDesc(userId);
    }

    public long countUnreadByUserId(String userId) {
        return notificationRepo.countByUsers_IdAndIsReadFalse(userId);
    }

    @Transactional
    public boolean deleteForUser(String notificationId, String userId) {
        if (notificationId == null || notificationId.isBlank() || userId == null || userId.isBlank()) {
            return false;
        }

        if (!notificationRepo.existsByIdAndUsers_Id(notificationId, userId)) {
            return false;
        }

        int affectedRows = notificationRepo.unlinkNotificationFromUser(notificationId, userId);
        if (affectedRows <= 0) {
            return false;
        }

        if (notificationRepo.countReceivers(notificationId) == 0) {
            notificationRepo.deleteById(notificationId);
        }

        return true;
    }

    public String cleanContent(String rawContent) {
        if (rawContent == null) {
            return "";
        }
        int markerIndex = rawContent.indexOf("||META:");
        if (markerIndex < 0) {
            return rawContent;
        }
        return rawContent.substring(0, markerIndex).trim();
    }

    public Optional<String> resolveRequestId(Notification notification) {
        if (notification == null) {
            return Optional.empty();
        }

        Map<String, String> metadata = extractMetadata(notification.getContent());

        String requestId = metadata.get("requestId");
        if (isPresent(requestId)) {
            return Optional.of(requestId);
        }

        String commentId = metadata.get("commentId");
        if (isPresent(commentId)) {
            return commentRepo.findById(commentId)
                    .map(comment -> comment.getRequest())
                    .filter(request -> request != null && request.getId() != null)
                    .map(request -> request.getId());
        }

        String voteCommentUserId = metadata.get("voteCommentUserId");
        String voteCommentCommentId = metadata.get("voteCommentCommentId");
        if (isPresent(voteCommentUserId) && isPresent(voteCommentCommentId)) {
            VoteCommentId voteCommentId = new VoteCommentId(voteCommentUserId, voteCommentCommentId);
            Optional<VoteComment> voteComment = voteCommentRepo.findById(voteCommentId);
            if (voteComment.isPresent()
                    && voteComment.get().getComment() != null
                    && voteComment.get().getComment().getRequest() != null
                    && voteComment.get().getComment().getRequest().getId() != null) {
                return Optional.of(voteComment.get().getComment().getRequest().getId());
            }
        }

        String voteUserId = metadata.get("voteUserId");
        String voteRequestId = metadata.get("voteRequestId");
        if (isPresent(voteUserId) && isPresent(voteRequestId)) {
            VoteId voteId = new VoteId(voteUserId, voteRequestId);
            return voteRepo.findById(voteId)
                    .map(v -> v.getRequest())
                    .filter(request -> request != null && request.getId() != null)
                    .map(request -> request.getId());
        }

        return Optional.empty();
    }

    public String appendMetadata(String content, Map<String, String> metadata) {
        if (metadata == null || metadata.isEmpty()) {
            return content == null ? "" : content;
        }

        StringBuilder builder = new StringBuilder(content == null ? "" : content.trim());
        builder.append(" ||META:");

        boolean first = true;
        for (Map.Entry<String, String> entry : metadata.entrySet()) {
            if (!isPresent(entry.getValue())) {
                continue;
            }
            if (!first) {
                builder.append(';');
            }
            builder.append(entry.getKey()).append('=').append(entry.getValue());
            first = false;
        }

        return builder.toString();
    }

    private Map<String, String> extractMetadata(String rawContent) {
        Map<String, String> map = new HashMap<>();
        if (rawContent == null) {
            return map;
        }

        int markerIndex = rawContent.indexOf("||META:");
        if (markerIndex < 0 || markerIndex + 7 >= rawContent.length()) {
            return map;
        }

        String metadataBlock = rawContent.substring(markerIndex + 7).trim();
        if (metadataBlock.isEmpty()) {
            return map;
        }

        String[] pairs = metadataBlock.split(";");
        for (String pair : pairs) {
            int equalIndex = pair.indexOf('=');
            if (equalIndex <= 0 || equalIndex >= pair.length() - 1) {
                continue;
            }
            String key = pair.substring(0, equalIndex).trim();
            String value = pair.substring(equalIndex + 1).trim();
            if (!key.isEmpty() && !value.isEmpty()) {
                map.put(key, value);
            }
        }

        return map;
    }

    private boolean isPresent(String value) {
        return value != null && !value.isBlank();
    }
}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.dto.CommentDTO;
import nvt.vn.ute_forum.model.Request;
