    /**
     * Tìm kiếm tất cả feedback - admin không lọc phòng ban
     */
    public Page<Request> searchAllFeedbacks(String keyword, Pageable pageable) {
        if (keyword == null || keyword.isBlank()) {
            return requestRepo.findAll(pageable);
        }
        return requestRepo.findAllByContentContaining(keyword.trim(), pageable);
    }

    /**
     * Lọc feedback theo departmentId + categoryId + status - dành cho admin
     * Không giới hạn phòng ban, lấy tất cả request kể cả ẩn danh
     */
    public Page<Request> getAdminFeedbacks(
            String departmentId,
            String categoryId,
            String status,
            Pageable pageable) {

        // Nếu không có filter nào -> lấy tất cả
        if (departmentId == null && categoryId == null && status == null) {
            return requestRepo.findAll(pageable);
        }

        // Có ít nhất 1 filter -> dùng query tổng hợp
        return requestRepo.adminFilterAll(departmentId, categoryId, status, pageable);
    }

    @Transactional
    public void updateStatus(String requestId, String newStatus) {

        Request request = requestRepo.findById(requestId)
                .orElseThrow(() -> new RuntimeException("Request not found"));

        String current = request.getCurrentStatus();

        //  RULE: Không cho update nếu đã kết thúc
        if (current.equals("RESOLVED") || current.equals("REJECTED")) {
            throw new RuntimeException("Không thể cập nhật trạng thái này nữa!");
        }

        // ✅ RULE chuyển trạng thái hợp lệ
        boolean valid = switch (current) {
            case "PENDING" ->
                    newStatus.equals("APPROVED") ||
                            newStatus.equals("RESOLVED") ||
                            newStatus.equals("REJECTED");
            case "APPROVED" -> newStatus.equals("RESOLVED") || newStatus.equals("REJECTED") || newStatus.equals("FORWARDING");
            default -> false;
        };

        if (!valid) {
            throw new RuntimeException("Chuyển trạng thái không hợp lệ!");
        }

        //  1. update current status
        request.setCurrentStatus(newStatus);
        requestRepo.save(request);

        //  2. lưu history
        RequestStatusHistory history = new RequestStatusHistory();
        history.setId("RSH_" + System.nanoTime());
        history.setStatus(newStatus);
        history.setCreateAt(LocalDateTime.now());
        history.setRequest(request);

        requestStatushistoryRepo.save(history);
    }

    @Transactional
    public void forwardRequest(String requestId,
                               String toDeptId,
                               String note,
                               Users user) {

        Request request = requestRepo.findById(requestId)
                .orElseThrow(() -> new RuntimeException("Request not found"));

        Department fromDept = request.getDepartment();

        Department toDept = departmentRepo.findById(toDeptId)
                .orElseThrow(() -> new RuntimeException("Department not found"));

        if (fromDept.getId().equals(toDeptId)) {
            throw new RuntimeException("Không thể chuyển cùng phòng");
        }

        request.setDepartment(toDept);
        request.setCurrentStatus("PENDING");

        requestRepo.save(request);

        forwardingLogService.createLog(request, fromDept, toDept, note, user);

        statusHistoryService.createForwardStatus(request);
    }


}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.dto.ReactionUserDTO;
import nvt.vn.ute_forum.dto.VoteResponse;
import nvt.vn.ute_forum.model.*;
import nvt.vn.ute_forum.repository.CommentRepo;
import nvt.vn.ute_forum.repository.UsersRepo;
import nvt.vn.ute_forum.repository.VoteCommentRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Service
public class VoteCommentService {

    @Autowired
    private VoteCommentRepo voteCommentRepository;
    @Autowired
    private UsersRepo usersRepo;
    @Autowired
    private CommentRepo commentRepo;

    @Transactional
    public VoteResponse toggleReaction(String username, String commentId, ReactionType type) {
        // 1. Lấy thông tin User từ DB (Dùng username từ Principal)
        Users user = usersRepo.findOptionalByEmail(username)
                .orElseThrow(() -> new RuntimeException("Không tìm thấy User: " + username));

        // 2. Lấy thông tin Comment từ DB
        Comment comment = commentRepo.findById(commentId)
                .orElseThrow(() -> new RuntimeException("Không tìm thấy Comment ID: " + commentId));

        // 3. TẠO ID Ở ĐÂY: Lấy chuỗi ID String của User và Comment ghép vào
        // Đây chính là lúc bạn "tạo" dãy String ID cho bản ghi Vote
        VoteCommentId id = new VoteCommentId(user.getId(), comment.getId());

        Optional<VoteComment> existing = voteCommentRepository.findById(id);

        boolean isVoted;
        String finalType = type.name();

        if (existing.isPresent()) {
            VoteComment vote = existing.get();
            if (vote.getType() == type) {
                // Nếu bấm lại icon cũ -> Xóa (Unlike)
                voteCommentRepository.delete(vote);
                isVoted = false;
                finalType = null;
            } else {
                // Nếu bấm icon khác -> Cập nhật loại cảm xúc
                vote.setType(type);
                vote.setVoteAt(LocalDateTime.now());
                voteCommentRepository.save(vote);
                isVoted = true;
            }
        } else {
            // 4. Nếu chưa có -> Tạo mới bản ghi VoteComment
            VoteComment newVote = new VoteComment();
            newVote.setId(id); // Gán dãy String ID vừa tạo ở trên vào
            newVote.setUser(user);
            newVote.setComment(comment);
            newVote.setType(type);
            newVote.setVoteAt(LocalDateTime.now());

            voteCommentRepository.save(newVote);
            isVoted = true;
        }

        long count = voteCommentRepository.countByIdCommentId(commentId);

//  LẤY TỪNG LOẠI REACTION
        List<Object[]> raw = voteCommentRepository.countReactionsByCommentId(commentId);

        Map<String, Long> reactions = new HashMap<>();
        for (Object[] row : raw) {
            reactions.put(row[0].toString(), (Long) row[1]);
        }

//  TRẢ FULL DATA
        return new VoteResponse(isVoted, finalType, count, reactions);
    }
    public List<ReactionUserDTO> getReactionUsers(String commentId) {
        return voteCommentRepository.findAllByCommentId(commentId)
                .stream()
                .map(row -> new ReactionUserDTO(
                        String.valueOf(row[0]),
                        (String) row[1],
                        row[2].toString(),
                        row[3].toString()           // userRole  Lấy trực tiếp giá trị DB
                ))
                .toList();
    }
}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.dto.ReactionUserDTO;
import nvt.vn.ute_forum.dto.VoteResponse;
import nvt.vn.ute_forum.model.*;
import nvt.vn.ute_forum.repository.CommentRepo;
import nvt.vn.ute_forum.repository.NotificationRepo;
import nvt.vn.ute_forum.repository.UsersRepo;
import nvt.vn.ute_forum.repository.VoteCommentRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Service
public class VoteCommentService {

    @Autowired
    private VoteCommentRepo voteCommentRepository;
    @Autowired
    private UsersRepo usersRepo;
    @Autowired
    private CommentRepo commentRepo;

    @Autowired
    private NotificationRepo notificationRepo;

    @Autowired
    private NotificationService notificationService;

    @Autowired
    private IdGeneratorService idGeneratorService;

    @Transactional
    public VoteResponse toggleReaction(String username, String commentId, ReactionType type) {
        // 1. Lấy thông tin User từ DB (Dùng username từ Principal)
        Users user = usersRepo.findOptionalByEmail(username)
                .orElseThrow(() -> new RuntimeException("Không tìm thấy User: " + username));

        // 2. Lấy thông tin Comment từ DB
        Comment comment = commentRepo.findById(commentId)
                .orElseThrow(() -> new RuntimeException("Không tìm thấy Comment ID: " + commentId));

        // 3. TẠO ID Ở ĐÂY: Lấy chuỗi ID String của User và Comment ghép vào
        // Đây chính là lúc bạn "tạo" dãy String ID cho bản ghi Vote
        VoteCommentId id = new VoteCommentId(user.getId(), comment.getId());

        Optional<VoteComment> existing = voteCommentRepository.findById(id);

        boolean isVoted;
        String finalType = type.name();

        boolean triggerNotification = false;

        if (existing.isPresent()) {
            VoteComment vote = existing.get();
            if (vote.getType() == type) {
                // Nếu bấm lại icon cũ -> Xóa (Unlike)
                voteCommentRepository.delete(vote);
                isVoted = false;
                finalType = null;
            } else {
                // Nếu bấm icon khác -> Cập nhật loại cảm xúc
                vote.setType(type);
                vote.setVoteAt(LocalDateTime.now());
                voteCommentRepository.save(vote);
                isVoted = true;
                triggerNotification = true;
            }
        } else {
            // 4. Nếu chưa có -> Tạo mới bản ghi VoteComment
            VoteComment newVote = new VoteComment();
            newVote.setId(id); // Gán dãy String ID vừa tạo ở trên vào
            newVote.setUser(user);
            newVote.setComment(comment);
            newVote.setType(type);
            newVote.setVoteAt(LocalDateTime.now());

            voteCommentRepository.save(newVote);
            isVoted = true;
            triggerNotification = true;
        }

        if (triggerNotification) {
            createCommentVoteNotification(comment, user, type);
        }

        long count = voteCommentRepository.countByIdCommentId(commentId);

//  LẤY TỪNG LOẠI REACTION
        List<Object[]> raw = voteCommentRepository.countReactionsByCommentId(commentId);

        Map<String, Long> reactions = new HashMap<>();
        for (Object[] row : raw) {
            reactions.put(row[0].toString(), (Long) row[1]);
        }

//  TRẢ FULL DATA
        return new VoteResponse(isVoted, finalType, count, reactions);
    }

    private void createCommentVoteNotification(Comment comment, Users actor, ReactionType type) {
        if (comment == null || comment.getRequest() == null || actor == null) {
            return;
        }

        Users postOwner = comment.getRequest().getUser();
        Users commentOwner = comment.getUser();

        String actorName = actor.getFullName() == null || actor.getFullName().isBlank() ? "Nguoi dung" : actor.getFullName();
        String content = actorName + " da tha " + type.name() + " cho mot binh luan trong bai viet cua ban.";

        Map<String, String> metadata = new HashMap<>();
        metadata.put("requestId", comment.getRequest().getId());
        metadata.put("commentId", comment.getId());
        metadata.put("voteCommentUserId", actor.getId());
        metadata.put("voteCommentCommentId", comment.getId());

        if (postOwner != null && postOwner.getId() != null && !postOwner.getId().equals(actor.getId())) {
            Notification notification = new Notification();
            notification.setId(idGeneratorService.nextNotificationId());
            notification.setNotificationType("VOTE_FORUM_POST_NOTIFICATION");
            notification.setTitle("Binh luan trong bai viet cua ban co tuong tac moi");
            notification.setContent(notificationService.appendMetadata(content, metadata));
            notification.setRead(false);
            notification.setCreateAt(LocalDateTime.now());
            notification.setUsers(List.of(postOwner));
            notificationRepo.save(notification);
        }

        if (commentOwner != null
                && commentOwner.getId() != null
                && !commentOwner.getId().equals(actor.getId())
                && (postOwner == null || !commentOwner.getId().equals(postOwner.getId()))) {
            Notification notification = new Notification();
            notification.setId(idGeneratorService.nextNotificationId());
            notification.setNotificationType("VOTE_FORUM_POST_NOTIFICATION");
            notification.setTitle("Binh luan cua ban vua co tuong tac");
            notification.setContent(notificationService.appendMetadata(content, metadata));
            notification.setRead(false);
            notification.setCreateAt(LocalDateTime.now());
            notification.setUsers(List.of(commentOwner));
            notificationRepo.save(notification);
        }
    }

    public List<ReactionUserDTO> getReactionUsers(String commentId) {
        return voteCommentRepository.findAllByCommentId(commentId)
                .stream()
                .map(row -> new ReactionUserDTO(
                        String.valueOf(row[0]),
                        (String) row[1],
                        row[2].toString(),
                        row[3].toString()           // userRole  Lấy trực tiếp giá trị DB
                ))
                .toList();
    }
}
